{"packet_id": "D026-01", "doc_id": "D026", "jurisdiction": "CA", "category": "application_screening_fees", "lifecycle": "enacted", "title": "California application screening fee cap", "requirement": "A landlord or agent may charge an applicant a screening fee only up to the actual out-of-pocket costs of gathering information about the applicant, and in no case more than thirty dollars per applicant, adjusted annually for the Consumer Price Index.", "key_value": "$30 per applicant, adjusted annually by CPI", "coverage_conditions": "Any applicant who requests to rent residential property from a landlord or the landlord’s agent.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": "1998-01-01", "citation": "Cal. Civ. Code § 1950.6: application screening fee cap", "quoted_span": "In no case shall the amount of the application screening fee charged by the landlord or their agent be greater than thirty dollars ($30) per applicant. The thirty dollar ($30) application screening fee may be adjusted annually by the landlord or their agent commensurate with an increase in the Consumer Price Index, beginning on January 1, 1998.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D026-01", "doc_id": "D026", "jurisdiction": "CA", "category": "application_screening_fees", "lifecycle": "enacted", "title": "California bar on screening fees when no unit is available", "requirement": "A landlord or agent may not charge an applicant an application screening fee when they know or should have known that no rental unit is available at that time or will be available within a reasonable period of time.", "key_value": null, "coverage_conditions": "Any applicant who requests to rent residential property from a landlord or the landlord’s agent.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Cal. Civ. Code § 1950.6: screening fee prohibited when no unit is available", "quoted_span": "(1) A landlord or their agent shall not charge an applicant an application screening fee when they know or should have known that no rental unit is available at that time or will be available within a reasonable period of time.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D026-01", "doc_id": "D026", "jurisdiction": "CA", "category": "application_screening_fees", "lifecycle": "enacted", "title": "California application screening fee refund conditions", "requirement": "A landlord may charge a screening fee only if it offers a process that refunds applicants whose application is not considered or who are not selected, within seven days, or within seven days of selecting a tenant or thirty days of submission, whichever occurs first.", "key_value": "7 days, or 30 days from application", "coverage_conditions": "Any applicant charged an application screening fee by a landlord or the landlord’s agent.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "No refund required for an applicant denied after consideration for failing to meet the landlord’s established screening criteria.", "penalty": null, "effective_date": null, "citation": "Cal. Civ. Code § 1950.6: screening fee refund requirements", "quoted_span": "(B) An application screening process in which the landlord or their agent returns the entire screening fee to any applicant who is not selected for tenancy, regardless of the reason, within 7 days of selecting an applicant for tenancy or 30 days of when the application was submitted, whichever occurs first.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D026-01", "doc_id": "D026", "jurisdiction": "CA", "category": "application_screening_fees", "lifecycle": "enacted", "title": "California screening fee receipt and credit report copy", "requirement": "A landlord who charges a screening fee must give the applicant a receipt itemizing out-of-pocket expenses and time spent, return any amount of the fee not used for authorized purposes, and provide a copy of the consumer credit report within seven days of receiving it.", "key_value": "7 days for credit report copy", "coverage_conditions": "Any applicant who paid an application screening fee to a landlord or the landlord’s agent.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Cal. Civ. Code § 1950.6: screening fee receipt and credit report disclosure", "quoted_span": "The landlord or their agent shall provide, personally, or by mail, the applicant with a receipt for the fee paid by the applicant, which receipt shall itemize the out-of-pocket expenses and time spent by the landlord or their agent to obtain and process the information about the applicant.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D026-01", "doc_id": "D026", "jurisdiction": "CA", "category": "screening_restrictions", "lifecycle": "enacted", "title": "California application processing order and first qualified applicant", "requirement": "A landlord charging a screening fee must consider completed applications in the order received under written screening criteria provided with the application form, and must approve the first applicant who meets those established criteria.", "key_value": null, "coverage_conditions": "Applicants screened by a landlord or the landlord’s agent that charges an application screening fee.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "applies when a landlord or agent charges an application screening fee"}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Cal. Civ. Code § 1950.6: application processing order and first-qualified-applicant approval", "quoted_span": "(i) Completed applications are considered, as provided for in the landlord’s established screening criteria, in the order in which the completed applications were received. The landlord’s screening criteria shall be provided to the applicant in writing together with the application form.\n(ii) The first applicant who meets the landlord’s established screening criteria is approved for tenancy.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
